//! Generated tables of abaplint's statement grammar plus a matcher that mirrors
//! abaplint's combinator semantics (`2_statements/combi.ts`), so a statement's words can be typed
//! KEYWORD (matched by `str()`) or IDENTIFIER (matched by `regex()`).
//!
//! `tables.rs` is generated by `tools/gen-grammar/gen.cjs`; do not edit it by hand.
use std::rc::Rc;
use std::sync::OnceLock;

use fancy_regex::Regex;

pub mod lexer;
mod parse;
#[rustfmt::skip]
mod tables;
pub use parse::{ParsedStatement, clear_memo, parse_statements};
pub use tables::{ABAPLINT_VERSION, EXPRESSIONS, NODES, RELEASES, STATEMENTS, Tk};

/// A combinator node. Children are indices into [`NODES`].
#[derive(Debug)]
pub enum Node {
    Word(&'static str),
    /// Pattern (JS syntax) and whether it is case-insensitive.
    Regex(&'static str, bool),
    Tok(Tk),
    Seq(&'static [u32]),
    Alt(&'static [u32]),
    AltPrio(&'static [u32]),
    Per(&'static [u32]),
    Opt(u32),
    OptPrio(u32),
    Star(u32),
    StarPrio(u32),
    Plus(u32),
    PlusPrio(u32),
    /// Release ordinal (index into [`RELEASES`]), "also in open-abap", child.
    Ver(u16, bool, u32),
    VerLang(u8, u32),
    VerNotLang(u8, u32),
    Fail,
    FailStar,
    StopBefore1(&'static [&'static str]),
    StopBefore2(&'static str, &'static str),
    Expr(u32),
}

pub struct Stmt {
    pub name: &'static str,
    /// Candidate first words (upper case); `""` means "any".
    pub first: &'static [&'static str],
    pub root: u32,
}

/// What a matched token turned out to be.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Class {
    /// Matched a literal word in the grammar (`str()`).
    Keyword,
    /// Matched by a pattern (`regex()`): a name, field, source, target...
    Identifier,
    /// Matched a punctuation token kind (`tok()`).
    Punct,
}

#[derive(Clone, Copy, Debug)]
pub struct Token<'a> {
    pub text: &'a str,
    pub kind: Tk,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LanguageVersion {
    KeyUser = 0,
    Cloud = 1,
    Normal = 2,
}

#[derive(Clone, Copy, Debug)]
pub struct Options {
    /// Index into [`RELEASES`].
    pub release: u16,
    pub language: LanguageVersion,
}

impl Default for Options {
    fn default() -> Self {
        Self {
            release: (RELEASES.len() - 1) as u16,
            language: LanguageVersion::Normal,
        }
    }
}

pub fn release_ordinal(name: &str) -> Option<u16> {
    RELEASES.iter().position(|r| *r == name).map(|i| i as u16)
}

enum Fail {
    Combinator,
    Star,
}

struct Path {
    tok: usize,
    class: Class,
    prev: Option<Rc<Path>>,
}

#[derive(Clone)]
struct St {
    pos: usize,
    path: Option<Rc<Path>>,
}

type Res = Result<Vec<St>, Fail>;

struct Matcher<'a> {
    tokens: &'a [Token<'a>],
    opts: Options,
}

impl<'a> Matcher<'a> {
    fn remaining(&self, s: &St) -> usize {
        self.tokens.len() - s.pos
    }

    fn shift(&self, s: &St, class: Class) -> St {
        St {
            pos: s.pos + 1,
            path: Some(Rc::new(Path {
                tok: s.pos,
                class,
                prev: s.path.clone(),
            })),
        }
    }

    fn regex(&self, id: u32) -> &'static Regex {
        static CACHE: OnceLock<Vec<OnceLock<Regex>>> = OnceLock::new();
        let cache = CACHE.get_or_init(|| (0..NODES.len()).map(|_| OnceLock::new()).collect());
        cache[id as usize].get_or_init(|| {
            let Node::Regex(pat, ci) = &NODES[id as usize] else {
                unreachable!()
            };
            Regex::new(&if *ci {
                format!("(?i){pat}")
            } else {
                (*pat).to_string()
            })
            .unwrap_or_else(|e| panic!("regex {pat}: {e}"))
        })
    }

    fn run(&self, id: u32, input: Vec<St>) -> Res {
        match &NODES[id as usize] {
            Node::Word(w) => Ok(input
                .into_iter()
                .filter(|s| {
                    self.remaining(s) != 0 && self.tokens[s.pos].text.eq_ignore_ascii_case(w)
                })
                .map(|s| self.shift(&s, Class::Keyword))
                .collect()),
            Node::Regex(..) => {
                let re = self.regex(id);
                Ok(input
                    .into_iter()
                    .filter(|s| {
                        self.remaining(s) != 0
                            && re.is_match(self.tokens[s.pos].text).unwrap_or(false)
                    })
                    .map(|s| self.shift(&s, Class::Identifier))
                    .collect())
            }
            Node::Tok(k) => Ok(input
                .into_iter()
                .filter(|s| self.remaining(s) != 0 && self.tokens[s.pos].kind == *k)
                .map(|s| self.shift(&s, Class::Punct))
                .collect()),
            Node::Seq(list) => {
                let mut result = Vec::new();
                for s in input {
                    let mut temp = vec![s];
                    for c in *list {
                        temp = self.run(*c, temp)?;
                        if temp.is_empty() {
                            break;
                        }
                    }
                    result.extend(temp);
                }
                Ok(result)
            }
            Node::Alt(list) => {
                let mut result = Vec::new();
                for c in *list {
                    result.extend(self.run(*c, input.clone())?);
                }
                Ok(result)
            }
            Node::AltPrio(list) => {
                for c in *list {
                    let temp = self.run(*c, input.clone())?;
                    if !temp.is_empty() {
                        return Ok(temp);
                    }
                }
                Ok(Vec::new())
            }
            Node::Per(list) => self.permutation(list, input),
            Node::Opt(c) => {
                let mut result = Vec::new();
                for s in input {
                    result.push(s.clone());
                    result.extend(self.run(*c, vec![s])?);
                }
                Ok(result)
            }
            Node::OptPrio(c) => {
                let mut result = Vec::new();
                for s in input {
                    let mut res = self.run(*c, vec![s.clone()])?;
                    if res.len() > 1 {
                        result.append(&mut res);
                    } else if res.is_empty() || res[0].pos <= s.pos {
                        result.push(s);
                    } else {
                        result.append(&mut res);
                    }
                }
                Ok(result)
            }
            Node::Star(c) => self.star(*c, input),
            Node::StarPrio(c) => self.star_prio(*c, input),
            // Plus is a sequence of (c, star(c)), and a sequence runs each input on its own.
            Node::Plus(c) | Node::PlusPrio(c) => {
                let prio = matches!(&NODES[id as usize], Node::PlusPrio(_));
                let mut result = Vec::new();
                for s in input {
                    let first = self.run(*c, vec![s])?;
                    if first.is_empty() {
                        continue;
                    }
                    result.extend(if prio {
                        self.star_prio(*c, first)?
                    } else {
                        self.star(*c, first)?
                    });
                }
                Ok(result)
            }
            Node::Ver(rel, open_abap, c) => {
                // open-abap sits at v702's ordinal in abaplint; we never run in that mode.
                let _ = open_abap;
                if self.opts.release >= *rel {
                    self.run(*c, input)
                } else {
                    Ok(Vec::new())
                }
            }
            Node::VerLang(lang, c) => {
                if (self.opts.language as u8) <= *lang {
                    self.run(*c, input)
                } else {
                    Ok(Vec::new())
                }
            }
            Node::VerNotLang(lang, c) => {
                if (self.opts.language as u8) > *lang {
                    self.run(*c, input)
                } else {
                    Ok(Vec::new())
                }
            }
            Node::Fail => Err(Fail::Combinator),
            Node::FailStar => Err(Fail::Star),
            Node::StopBefore1(words) => Ok(input
                .into_iter()
                .filter(|s| {
                    self.tokens
                        .get(s.pos)
                        .is_some_and(|t| !words.iter().any(|w| t.text.eq_ignore_ascii_case(w)))
                })
                .collect()),
            Node::StopBefore2(a, b) => Ok(input
                .into_iter()
                .filter(|s| match self.tokens.get(s.pos) {
                    None => false,
                    Some(t) => {
                        !(t.text.eq_ignore_ascii_case(a)
                            && self
                                .tokens
                                .get(s.pos + 1)
                                .is_some_and(|n| n.text.eq_ignore_ascii_case(b)))
                    }
                })
                .collect()),
            Node::Expr(e) => {
                // An expression runs each input on its own, which matters for the Prio variants.
                let root = EXPRESSIONS[*e as usize].1;
                let mut result = Vec::new();
                for s in input {
                    result.extend(self.run(root, vec![s])?);
                }
                Ok(result)
            }
        }
    }

    fn star(&self, c: u32, input: Vec<St>) -> Res {
        let mut result = input.clone();
        let mut res = input;
        loop {
            res = match self.run(c, res) {
                Ok(r) => r,
                Err(Fail::Star) => return Ok(result),
                Err(e) => return Err(e),
            };
            if res.is_empty() {
                break;
            }
            result.extend(res.iter().cloned());
        }
        Ok(result)
    }

    fn star_prio(&self, c: u32, input: Vec<St>) -> Res {
        let mut result = input.clone();
        let mut res = input;
        let mut prev: Option<Vec<St>> = None;
        loop {
            res = self.run(c, res)?;
            if res.is_empty() {
                if let Some(prev) = prev {
                    // the first state with the fewest tokens remaining, like abaplint
                    let mut first_best: Option<St> = None;
                    for p in &prev {
                        if first_best.as_ref().is_none_or(|b| p.pos > b.pos) {
                            first_best = Some(p.clone());
                        }
                    }
                    result = first_best.into_iter().collect();
                }
                break;
            }
            prev = Some(res.clone());
        }
        Ok(result)
    }

    /// Mirrors abaplint's `Permutation.run`, including that `left` is one list shared across the
    /// loop iterations (so later indices refer to an already shrunken list).
    fn permutation(&self, list: &[u32], input: Vec<St>) -> Res {
        let mut result = Vec::new();
        let mut copy: Vec<u32> = list.to_vec();
        for (index, item) in list.iter().enumerate() {
            let temp = self.run(*item, input.clone())?;
            if temp.is_empty() {
                continue;
            }
            result.extend(temp.iter().cloned());
            if index < copy.len() {
                copy.remove(index);
            }
            match copy.len() {
                0 => {}
                1 => result.extend(self.run(copy[0], temp)?),
                _ => {
                    let left = copy.clone();
                    result.extend(self.permutation(&left, temp)?);
                }
            }
        }
        Ok(result)
    }
}

/// Result of matching one statement.
#[derive(Debug)]
pub struct Matched {
    pub statement: &'static str,
    /// One entry per input token; `None` for a token the grammar consumed in no way we track
    /// (cannot happen for a full match).
    pub classes: Vec<Option<Class>>,
}

fn try_statement(
    st: &Stmt,
    tokens: &[Token],
    opts: Options,
    matcher: &Matcher,
) -> Option<Vec<Option<Class>>> {
    let _ = (st, opts);
    let res = matcher.run(st.root, vec![St { pos: 0, path: None }]);
    let res = match res {
        Ok(r) => r,
        Err(Fail::Combinator) | Err(Fail::Star) => return None,
    };
    let full = res.into_iter().find(|s| s.pos == tokens.len())?;
    let mut classes = vec![None; tokens.len()];
    let mut p = full.path;
    while let Some(n) = p {
        classes[n.tok] = Some(n.class);
        p = n.prev.clone();
    }
    Some(classes)
}

/// Match the tokens of one statement (without its closing period, pragmas removed) the way
/// abaplint's `StatementParser.match` does: statements keyed by first word, then the unkeyed
/// ones, first full match wins.
pub fn match_statement(tokens: &[Token], opts: Options) -> Option<Matched> {
    let first = tokens.first()?.text.to_ascii_uppercase();
    let matcher = Matcher { tokens, opts };
    for pass in [first.as_str(), ""] {
        for st in STATEMENTS.iter().filter(|s| s.first.contains(&pass)) {
            if let Some(classes) = try_statement(st, tokens, opts, &matcher) {
                return Some(Matched {
                    statement: st.name,
                    classes,
                });
            }
        }
    }
    None
}

/// Is `word` (any case) one of the words the grammar matches literally? This is the keyword set
/// used by the fallback refiner for statements the grammar cannot parse.
pub fn is_grammar_word(word: &str) -> bool {
    static WORDS: OnceLock<std::collections::HashSet<&'static str>> = OnceLock::new();
    WORDS
        .get_or_init(|| {
            NODES
                .iter()
                .filter_map(|n| match n {
                    Node::Word(w) => Some(*w),
                    _ => None,
                })
                .collect()
        })
        .contains(word.to_ascii_uppercase().as_str())
}
